    names=[x.strip() for x in m.group(1).split(',') if x.strip()]
    if 'requireOpenOrg' not in names: names.append('requireOpenOrg')
    if 'requireFound' in names and 'requireFound(' not in s.replace('import','') : names.remove('requireFound')
    names=sorted(names,key=lambda x:x.lower())
    s=s.replace(m.group(0),'import { '+', '.join(names)+' } from "./_support";')
    if 'orgRepo.' not in s:
        s=re.sub(r'import \* as orgRepo from "[^"]+";\n','',s)
    open(p,'w').write(s)
