import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("./server/_support/doubles/misc")).rateLimitModule);

import { emit, subscribe } from "@/lib/event-bus";
import { hashToken } from "@/lib/hash";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { runOverdueIssueJob, resetOverdueTracking } from "@/server/jobs/overdue-issue-job";
import { runSearchReindexJob } from "@/server/jobs/search-reindex-job";
import { runTrialExpiryJob } from "@/server/jobs/trial-expiry-job";
import { runWebhookDeliveryJob } from "@/server/jobs/webhook-delivery-job";
import { runDigestEmailJob } from "@/server/jobs/digest-email-job";
import { registerEventHandlers } from "@/server/services/event-registry";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as sessionRepo from "@/server/repositories/session-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as webhookRepo from "@/server/repositories/webhook-repository";
import * as activityRepo from "@/server/repositories/activity-repository";
import { acceptInvitation } from "@/server/services/invitation-service";
import { createOrganization, deleteOrganization, getOrganizationSummary, listOrganizationsForUser, resolveOrgBySlug } from "@/server/services/organization-service";
import { createSessionToken, resolveActorForOrg, resolveSession, switchActiveOrg } from "@/server/services/session-service";
import { resolveActor, listMembers } from "@/server/services/member-service";
import { listProjects } from "@/server/services/project-service";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "./server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  registerEventHandlers();
});
afterAll(() => cleanup());

const NOW = new Date("2026-06-01T07:00:00.000Z");

describe("closure scenario", () => {
  it("works end to end", async () => {
    const t = await createTenant("closeme", "growth");
    const o = await createTenant("other", "growth");
    // share a member: owner of `closeme` is also a member of `other`
    await memberRepo.insertMember(o.org.id, t.userIds.member, "member", null);

    await usageRepo.recomputeUsage(t.org.id);
    await usageRepo.recomputeUsage(o.org.id);

    // overdue issues in both
    const n1 = await issueRepo.nextIssueNumber(t.org.id, t.project.id);
    await issueRepo.insertIssue(issueInput(t.org.id, t.project.id, { assigneeId: t.userIds.member, dueAt: "2026-01-01T00:00:00.000Z" }), t.userIds.owner, n1);
    const n2 = await issueRepo.nextIssueNumber(o.org.id, o.project.id);
    await issueRepo.insertIssue(issueInput(o.org.id, o.project.id, { assigneeId: o.userIds.member, dueAt: "2026-01-01T00:00:00.000Z" }), o.userIds.owner, n2);

    // webhook endpoint + queued delivery, trial subscription
    const ep = await webhookRepo.insertEndpoint({ orgId: t.org.id, url: "https://x.test/h", eventTypes: ["billing.plan_changed"] } as never, "secret");
    await webhookRepo.enqueueDelivery(t.org.id, ep.id, "issue.created", "{}");
    const epo = await webhookRepo.insertEndpoint({ orgId: o.org.id, url: "https://y.test/h", eventTypes: ["billing.plan_changed"] } as never, "secret");
    await webhookRepo.enqueueDelivery(o.org.id, epo.id, "issue.created", "{}");

    // session valid before
    const { token } = await createSessionToken(t.userIds.member);
    let principal = await resolveSession(token);
    expect(principal).not.toBeNull();
    expect(await resolveActorForOrg(principal!, "closeme")).not.toBeNull();

    // pending invitation
    const inv = await invitationRepo.insertInvitation(t.org.id, { orgId: t.org.id, email: "new@x.test", role: "member", expiresInDays: 14 }, t.userIds.owner, hashToken("tok-abc"));
    const newcomer = await userRepo.insertUser({ email: "newcomer@x.test", name: "N", passwordHash: "seed" });

    // wrong confirmation
    await expect(deleteOrganization(t.actors.owner, { orgId: t.org.id, confirmSlug: "nope" as never })).rejects.toThrow(/confirmation/);
    expect((await orgRepo.findOrgById(t.org.id))!.archivedAt).toBeNull();

    // close
    const closed = await deleteOrganization(t.actors.owner, { orgId: t.org.id, confirmSlug: "closeme" as never });
    expect(closed.archivedAt).not.toBeNull();
    const sub = await subscriptionRepo.findSubscription(t.org.id);
    expect(sub!.status).toBe("canceled");

    // second close
    await expect(deleteOrganization(t.actors.owner, { orgId: t.org.id, confirmSlug: "closeme" as never })).rejects.toBeInstanceOf(AlreadyArchivedError);

    // 1: list / open / switch
    expect((await listOrganizationsForUser(t.userIds.member)).map((x) => x.slug).sort()).toEqual(["other"]);
    principal = await resolveSession(token);
    expect(await resolveActorForOrg(principal!, "closeme")).toBeNull();
    expect(await resolveActor(t.userIds.member, t.org.id)).toBeNull();
    expect(await resolveOrgBySlug("closeme")).toBeNull();
    await expect(switchActiveOrg(principal!, { orgId: t.org.id })).rejects.toThrow();
    await expect(getOrganizationSummary(t.actors.owner, t.org.id)).rejects.toThrow();
    await expect(listProjects(t.actors.member, { orgId: t.org.id, limit: 10 } as never)).rejects.toThrow();
    await expect(listMembers(t.actors.member, { orgId: t.org.id, limit: 10, cursor: null } as never)).rejects.toThrow();
    // other workspace unaffected
    expect(await resolveActorForOrg(principal!, "other")).not.toBeNull();
    await switchActiveOrg(principal!, { orgId: o.org.id });
    await getOrganizationSummary(o.actors.owner, o.org.id);

    // 2: invitation
    await expect(acceptInvitation(newcomer.id, { token: "tok-abc" } as never)).rejects.toThrow();
    expect(await memberRepo.findMember(t.org.id, newcomer.id)).toBeNull();
    const before = await notificationRepo.countUnread(t.org.id, t.userIds.owner);
    await emit("member.joined", { orgId: t.org.id, actorId: newcomer.id, occurredAt: toIsoTimestamp(new Date()), memberId: "m" as never, userId: newcomer.id, role: "member" });
    expect(await notificationRepo.countUnread(t.org.id, t.userIds.owner)).toBe(before);

    // 3: overdue
    resetOverdueTracking();
    const seen: string[] = [];
    const off = subscribe("issue.overdue", (p) => { seen.push(p.orgId); });
    await runOverdueIssueJob(NOW);
    off();
    expect(seen).toEqual([o.org.id]);
    expect(await notificationRepo.countUnread(t.org.id, t.userIds.member)).toBe(0);
    expect(await notificationRepo.countUnread(o.org.id, o.userIds.member)).toBe(1);

    // 4: webhooks (queued before closing + a new one inserted after)
    await webhookRepo.enqueueDelivery(t.org.id, ep.id, "issue.created", "{}");
    const wr = await runWebhookDeliveryJob(NOW);
    expect(wr.processed).toBe(1); // only the other org
    expect(wr.failed).toBe(0);

    // 5: trial expiry
    const trialing = await createTenant("trial-closed", "growth");
    await usageRepo.recomputeUsage(trialing.org.id);
    // make the trial expired then close via repo only
    const { getDb, subscriptions } = await import("@/server/db");
    const { eq } = await import("drizzle-orm");
    getDb().update(subscriptions).set({ status: "trialing", currentPeriodEnd: "2026-01-01T00:00:00.000Z" }).where(eq(subscriptions.orgId, trialing.org.id)).run();
    await orgRepo.archiveOrg(trialing.org.id);
    const plan: string[] = [];
    const off2 = subscribe("billing.plan_changed", (p) => { plan.push(p.orgId); });
    await runTrialExpiryJob(NOW);
    off2();
    expect(plan).toEqual([]);
    const acts = await activityRepo.listActivity({ orgId: trialing.org.id, limit: 50, cursor: null } as never);
    expect(acts.items.filter((a) => a.action === "billing.plan_changed")).toHaveLength(0);

    // direct bus event on a closed org doesn't create audit/webhook rows
    await emit("billing.plan_changed", { orgId: t.org.id, actorId: null, occurredAt: toIsoTimestamp(new Date()), from: "growth", to: "free" });
    const acts2 = await activityRepo.listActivity({ orgId: t.org.id, limit: 50, cursor: null } as never);
    expect(acts2.items.filter((a) => a.action === "billing.plan_changed")).toHaveLength(0);

    // digest job doesn't blow up
    await runDigestEmailJob(NOW);

    // 6: reindex
